import { proxyActivities, sleep } from "@temporalio/workflow";
import type * as activities from "./activities";

const { writePlan, openPr } = proxyActivities<typeof activities>({ startToCloseTimeout: "1 minute" });

export async function ticketToPr(ticket: string): Promise<string> {
  const plan = await writePlan(ticket);
  await sleep("3 days"); // in the real run: wait until the requester approves
  const pr = await openPr(ticket);
  return `${plan}, then ${pr}`;
}

