// The workflow decides what happens and in which order. It never talks to the outside world itself.
import { proxyActivities, sleep } from '@temporalio/workflow';

const { writePlan, openPr } = proxyActivities({ startToCloseTimeout: '1 minute' });

export async function ticketToPr(ticket) {
  const plan = await writePlan(ticket);
  await sleep('30 seconds'); // stands in for "wait three days for the requester to approve"
  const pr = await openPr(ticket);
  return `${plan}, then ${pr}`;
}
EOF

