// A client: it asks Temporal to start one run, then leaves.
import { Client, Connection } from '@temporalio/client';

const connection = await Connection.connect({ address: 'localhost:7233' });
const client = new Client({ connection });
const ticket = process.argv[2] ?? 'RH-1234';
const handle = await client.workflow.start('ticketToPr', {
  workflowId: `nova:${ticket}`,
  taskQueue: 'ai-agents-nova',
  args: [ticket],
});
console.log(`Started ${handle.workflowId}. The worker does the rest.`);
await connection.close();
EOF

