// workflows.mjs
import { proxyActivities, sleep } from '@temporalio/workflow';

const { writePlan, openPr, askForReview } = proxyActivities({ startToCloseTimeout: '1 minute' });

export async function ticketToPr(ticket) {
  const plan = await writePlan(ticket);
  await sleep('30 seconds');
  const pr = await openPr(ticket);
  const review = await askForReview(pr);
  return `${plan}, then ${pr}, then ${review}`;
}
